on conflict(side,market,category_key,source_url,business_name) do update set
 snippet=excluded.snippet,source_tier='registry_derived',verification_status='credential_corroborated',
 last_verified_at=excluded.last_verified_at,
 status=case when market_inventory_candidates.status='closed' then 'closed' else 'discovered' end,
 last_seen_at=now(),evidence=market_inventory_candidates.evidence || excluded.evidence,updated_at=now();

update market_inventory_progress p set official_candidates=(
 select count(*) from market_inventory_candidates c where c.side=p.side and c.market=p.market and c.category_key=p.category_key
 and c.status='discovered' and c.query_strategy_version=7 and c.official_site=true
),updated_at=now() where p.market='Tucson' and p.side='vendor' and p.category_key='hvac_heat';


